            expect(first?.fingerprintHint).toContain('seat-legal-only:1:defensiveRoll:seat-legal-only-attempt-a');
            expect(second?.fingerprintHint).toContain('seat-legal-only:1:defensiveRoll:seat-legal-only-attempt-b');
